<script>
 import {onMount} from 'svelte';import {getMonitoring,refreshDeviceMetrics} from '$lib/api.js';import {notify} from '$lib/stores.js';import Button from '$lib/components/Button.svelte';import StatusDot from '$lib/components/StatusDot.svelte';
 let data=null,loading=true;
 async function load(){loading=true;const first=await getMonitoring();if(first.ok){const online=first.data.devices.filter(d=>d.status==='online');await Promise.all(online.map(d=>refreshDeviceMetrics(d.id)));const latest=await getMonitoring();data=latest.ok?latest.data:first.data}else notify(first.error||'Не удалось загрузить мониторинг','error');loading=false}
 function sparkline(points,key){if(!points?.length)return '';const values=points.map(p=>Number(p[key]||0));return values.map((v,i)=>`${values.length===1?50: i*100/(values.length-1)},${24-Math.max(0,Math.min(100,v))*0.22}`).join(' ')}
 onMount(load);
</script>
<div class="page-header"><div><div class="eyebrow">OBSERVABILITY</div><h1 class="page-title">Monitoring</h1><p class="page-desc">Состояние устройств, сайтов и Database Servers по последним heartbeat и статусам.</p></div><Button on:click={load}>↻ Обновить</Button></div>
{#if loading}<div class="empty">Собираем данные…</div>{:else if data}
<div class="metrics"><div><small>Devices online</small><strong>{data.summary.online_devices} <em>/ {data.summary.devices}</em></strong></div><div><small>Running websites</small><strong>{data.summary.running_sites} <em>/ {data.summary.sites}</em></strong></div><div><small>Database Servers</small><strong>{data.summary.database_servers}</strong></div></div>
<div class="notice">Показатели собираются с онлайн-устройств при обновлении страницы. Температура зависит от доступности thermal sysfs на конкретном Android-устройстве.</div>
<h2 class="section-title">Device health</h2>
{#if data.devices.length}<div class="device-list">{#each data.devices as d}<article class="device"><span class="device-icon">▣</span><div class="device-copy"><strong>{d.hostname}</strong><small>Agent {d.agent_version||'—'} · {d.site_count} websites · {d.running_sites} running</small><small>CPU {d.metrics?.cpu_percent!=null?d.metrics.cpu_percent.toFixed(1)+'%':'—'} · RAM {d.metrics?.memory_available_bytes!=null?(d.metrics.memory_available_bytes/1073741824).toFixed(2)+' GB free':'—'} · Storage {d.metrics?.storage_available_bytes!=null?(d.metrics.storage_available_bytes/1073741824).toFixed(1)+' GB free':'—'} · Temp {d.metrics?.temperature_celsius!=null?d.metrics.temperature_celsius.toFixed(1)+'°C':'—'}</small><div class="sparklines"><div><span>CPU</span><svg viewBox="0 0 100 24" preserveAspectRatio="none"><polyline points={sparkline(d.history,'cpu_percent')} fill="none" stroke="#3B82F6" stroke-width="2" vector-effect="non-scaling-stroke"/></svg></div><div><span>RAM</span><svg viewBox="0 0 100 24" preserveAspectRatio="none"><polyline points={sparkline(d.history,'memory_used_percent')} fill="none" stroke="#22C55E" stroke-width="2" vector-effect="non-scaling-stroke"/></svg></div></div></div><span class="device-status"><StatusDot status={d.status}/>{d.status}</span><time>{d.last_seen?new Date(d.last_seen).toLocaleString():'Never seen'}</time></article>{/each}</div>{:else}<div class="empty">Нет подключённых устройств.</div>{/if}
{/if}
<style>
.eyebrow{font-size:9px;letter-spacing:.14em;color:#818cf8;font-weight:700;margin-bottom:7px}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.metrics>div{display:grid;gap:8px;padding:14px;background:#101727;border:1px solid #253149;border-radius:10px}.metrics small{font-size:9px;color:#64748b}.metrics strong{font-size:22px}.metrics em{font-size:11px;color:#64748b;font-style:normal;font-weight:500}.notice{margin:13px 0 24px;padding:11px 13px;border:1px solid #334155;background:#101727;border-radius:9px;color:#94a3b8;font-size:10px;line-height:1.6}.section-title{font-size:12px;margin-bottom:10px}.device-list{border:1px solid #253149;border-radius:11px;background:#101727;overflow:hidden}.device{display:flex;align-items:center;gap:10px;padding:11px;border-bottom:1px solid #1e293b}.device:last-child{border:0}.device-icon{width:29px;height:29px;display:grid;place-items:center;background:#172136;color:#a5b4fc;border-radius:8px}.device-copy{display:grid;gap:3px;flex:1;min-width:0}.device-copy strong{font-size:10px}.device-copy small,.device time,.device-status{font-size:9px;color:#64748b}.sparklines{display:flex;gap:12px;margin-top:5px}.sparklines>div{display:flex;align-items:center;gap:5px;width:120px}.sparklines span{font-size:8px;color:#71717a;width:24px}.sparklines svg{width:90px;height:22px;overflow:visible}.device-status{display:flex;align-items:center;gap:6px}.device time{white-space:nowrap}
@media(max-width:700px){.metrics{grid-template-columns:1fr}.device{flex-wrap:wrap}.device time{margin-left:39px;width:100%}}
</style>